#!/usr/bin/env python3
"""Write the Homebrew formula for a circitor release.

    python3 .github/scripts/homebrew_formula.py VERSION CHECKSUMS > Formula/circitor.rb

VERSION is the release's tag, with or without the leading "v" (v0.0.1).
CHECKSUMS is the release's checksums.txt: `sha256sum` output for the
circitor_VERSION_OS_ARCH.tar.gz archives.

A formula, not a cask (D5, OPS-10): Homebrew quarantines a cask's download, so
its binary would need notarising; a formula's isn't quarantined. It has no
`service do` block: no `brew services` in v1 (OPS-10, OPS-18).
Standard library only.
"""

import sys

REPO = "https://github.com/yachiko/circitor"

# OS block: its CPU blocks and each archive's suffix. macOS is arm64 only (D17, OPS-13).
PLATFORMS = {
    "on_macos": {"on_arm": "darwin_arm64"},
    "on_linux": {"on_arm": "linux_arm64", "on_intel": "linux_amd64"},
}

TEMPLATE = """\
# This file is generated by circitor's release workflow. DO NOT EDIT.
class Circitor < Formula
  desc "Local daemon that watches GitHub pull requests for coding agents"
  homepage "{repo}"
  version "{version}"
  license "MIT"

{platforms}
  def install
    bin.install "circitor"
  end

  test do
    assert_match "circitor #{{version}}+", shell_output("#{{bin}}/circitor version")
  end
end
"""


def read_checksums(path):
    sums = {}
    with open(path) as f:
        for line in f:
            if line.strip():
                digest, name = line.split()
                sums[name.lstrip("*")] = digest
    return sums


def platform_blocks(version, sums):
    lines = []
    for os_block, cpus in PLATFORMS.items():
        lines.append(f"  {os_block} do")
        if os_block == "on_macos":
            # An Intel Mac gets a clear refusal, not a formula without a URL.
            lines.append("    depends_on arch: :arm64")
        for cpu_block, suffix in cpus.items():
            archive = f"circitor_{version}_{suffix}.tar.gz"
            if archive not in sums:
                sys.exit(f"homebrew_formula: {archive} is missing from the checksums")
            lines += [
                f"    {cpu_block} do",
                f'      url "{REPO}/releases/download/v{version}/{archive}"',
                f'      sha256 "{sums[archive]}"',
                "    end",
            ]
        lines.append("  end")
    return "\n".join(lines) + "\n"


def main():
    if len(sys.argv) != 3:
        sys.exit("usage: homebrew_formula.py VERSION CHECKSUMS")
    version, checksums = sys.argv[1].removeprefix("v"), sys.argv[2]
    sums = read_checksums(checksums)
    sys.stdout.write(
        TEMPLATE.format(repo=REPO, version=version, platforms=platform_blocks(version, sums))
    )


if __name__ == "__main__":
    main()
